-- Owner requested fix 2026-10-21. Exact one-RPC ACL change;32-table catalog held constant.
-- Target lvnvkpyxtuilhrabtlwv. No table/policy/body/role/schema/data mutation.
BEGIN; SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
DO $rpc_precondition$ DECLARE actual jsonb; BEGIN SELECT evidence INTO actual FROM (SELECT jsonb_build_object('tables',(SELECT evidence FROM (WITH targets AS (
 SELECT c.oid,c.relname,c.relkind,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relacl
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relname=ANY(ARRAY['edu_comm_acknowledgements','edu_comm_consent_responses','edu_comm_deliveries','edu_comm_delivery_attempts','edu_comm_exceptions','edu_comm_notices','edu_comm_responses','edu_comm_sent_snapshots','edu_comm_threads','edu_fac_assets','edu_fac_facilities','edu_fac_inspection_logs','edu_fac_inspection_schedules','edu_fac_maintenance_jobs','edu_fac_out_of_service_logs','edu_fac_zones','edu_fin_billing_periods','edu_fin_fee_structures','edu_fin_invoice_line_items','edu_fin_invoices','edu_fin_payments','edu_fin_receipts','edu_fin_reconciliation_ledger','edu_fin_student_discount_profiles','edu_sched_compliance_snapshots','edu_sched_leave_requests','edu_sched_ratio_policies','edu_sched_shift_assignments','edu_sched_shift_templates','edu_sched_staff_availability','edu_sched_substitutions','students'])
), grants AS (
 SELECT t.relname AS table_name,pg_get_userbyid(a.grantor) AS grantor,
 CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS grantee,a.privilege_type,a.is_grantable
 FROM targets t CROSS JOIN LATERAL aclexplode(coalesce(t.relacl,acldefault('r',t.relowner))) a
), cols AS (
 SELECT t.relname AS table_name,a.attname AS name,format_type(a.atttypid,a.atttypmod) AS type,
 a.attnotnull AS not_null,a.attidentity,a.attgenerated,a.attacl::text AS acl,pg_get_expr(ad.adbin,ad.adrelid) AS default_expression
 FROM targets t JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped
 LEFT JOIN pg_attrdef ad ON ad.adrelid=t.oid AND ad.adnum=a.attnum
), constraints AS (
 SELECT t.relname AS table_name,c.conname,c.contype,pg_get_constraintdef(c.oid,true) AS definition
 FROM targets t JOIN pg_constraint c ON c.conrelid=t.oid
), triggers AS (
 SELECT t.relname AS table_name,tr.tgname,pg_get_triggerdef(tr.oid,true) AS definition
 FROM targets t JOIN pg_trigger tr ON tr.tgrelid=t.oid WHERE NOT tr.tgisinternal
), views AS (
 SELECT DISTINCT t.relname AS target,n.nspname AS schema,v.relname AS name,v.reloptions,
 has_table_privilege('anon',v.oid,'SELECT') AS anon_select,pg_get_viewdef(v.oid,true) AS definition
 FROM targets t JOIN pg_depend dep ON dep.refobjid=t.oid JOIN pg_rewrite rw ON rw.oid=dep.objid
 JOIN pg_class v ON v.oid=rw.ev_class JOIN pg_namespace n ON n.oid=v.relnamespace WHERE v.relkind IN ('v','m') AND v.oid<>t.oid
), functions AS (
 SELECT n.nspname AS schema,p.proname AS name,pg_get_function_identity_arguments(p.oid) AS arguments,
 pg_get_userbyid(p.proowner) AS owner,p.prosecdef AS security_definer,p.proacl::text AS acl,p.proconfig,
 pg_get_functiondef(p.oid) AS definition
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE p.prokind='f' AND ((n.nspname='public' AND (p.proname IN ('get_auth_tenant_id','get_my_tenant_id','is_admin','is_hq_admin','is_hq_super_admin','fn_check_sent_snapshot_immutable','fn_check_invoice_line_items_immutable','fn_check_invoice_immutable','update_students_updated_at') OR EXISTS(SELECT 1 FROM targets t WHERE position(t.relname IN lower(p.prosrc))>0))) OR (n.nspname='auth' AND p.proname IN ('jwt','uid')))
)
SELECT jsonb_build_object(
 'tables',coalesce((SELECT jsonb_agg(jsonb_build_object('name',t.relname,'kind',t.relkind,'owner',pg_get_userbyid(t.relowner),'rls_enabled',t.relrowsecurity,'rls_forced',t.relforcerowsecurity) ORDER BY t.relname) FROM targets t),'[]'::jsonb),
 'grants',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.table_name,g.grantee,g.privilege_type,g.grantor) FROM grants g),'[]'::jsonb),
 'columns',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.table_name,c.name) FROM cols c),'[]'::jsonb),
 'constraints',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.table_name,c.conname) FROM constraints c),'[]'::jsonb),
 'triggers',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.table_name,t.tgname) FROM triggers t),'[]'::jsonb),
 'policies',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.tablename,p.policyname) FROM pg_policies p WHERE p.schemaname='public' AND p.tablename IN (SELECT relname FROM targets)),'[]'::jsonb),
 'functions',coalesce((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.schema,f.name,f.arguments) FROM functions f),'[]'::jsonb),
 'views',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.target,v.schema,v.name) FROM views v),'[]'::jsonb),
 'roles',coalesce((SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'superuser',r.rolsuper,'inherit',r.rolinherit,'bypass_rls',r.rolbypassrls,'can_login',r.rolcanlogin) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role','authenticator','postgres')),'[]'::jsonb),
 'memberships',coalesce((SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'admin_option',m.admin_option) ORDER BY pg_get_userbyid(m.roleid),pg_get_userbyid(m.member)) FROM pg_auth_members m WHERE pg_get_userbyid(m.member) IN ('anon','authenticated','service_role','authenticator')),'[]'::jsonb),
 'schema_grants',coalesce((SELECT jsonb_agg(jsonb_build_object('role',r.role,'usage',has_schema_privilege(r.role,'public','USAGE'),'create',has_schema_privilege(r.role,'public','CREATE')) ORDER BY r.role) FROM (VALUES ('anon'),('authenticated'),('service_role')) r(role)),'[]'::jsonb),
 'defaults',coalesce((SELECT jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(a.defaclrole),'namespace',coalesce(n.nspname,''),'object_type',a.defaclobjtype,'acl',a.defaclacl::text) ORDER BY pg_get_userbyid(a.defaclrole),coalesce(n.nspname,''),a.defaclobjtype) FROM pg_default_acl a LEFT JOIN pg_namespace n ON n.oid=a.defaclnamespace WHERE n.nspname='public' OR a.defaclnamespace=0),'[]'::jsonb)
) AS evidence) t),'rpc',(SELECT evidence FROM (SELECT evidence - 'memberships' || jsonb_build_object('memberships',(SELECT jsonb_agg(m - 'grantor' ORDER BY m->>'role',m->>'member') FROM jsonb_array_elements(evidence->'memberships') m)) AS evidence FROM (WITH rpc AS (
 SELECT p.oid,n.nspname AS schema,p.proname AS name,
 pg_get_function_identity_arguments(p.oid) AS arguments,
 pg_get_userbyid(p.proowner) AS owner,p.prosecdef AS security_definer,
 p.proacl::text AS acl,p.proconfig,pg_get_functiondef(p.oid) AS definition
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE p.oid=to_regprocedure('public.exec_sql(text)')
)
SELECT jsonb_build_object(
 'function',(SELECT to_jsonb(f)-'oid' FROM rpc f),
 'function_grants',coalesce((SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,pg_get_userbyid(a.grantor)) FROM rpc f JOIN pg_proc p ON p.oid=f.oid CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a),'[]'::jsonb),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'superuser',r.rolsuper,'inherit',r.rolinherit,'bypass_rls',r.rolbypassrls,'login',r.rolcanlogin,'execute',has_function_privilege(r.oid,'public.exec_sql(text)','EXECUTE'),'grant_option',has_function_privilege(r.oid,'public.exec_sql(text)','EXECUTE WITH GRANT OPTION')) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname<>'acl_rehearsal_superuser'),
 'memberships',coalesce((SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'grantor',pg_get_userbyid(m.grantor),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) ORDER BY pg_get_userbyid(m.roleid),pg_get_userbyid(m.member),pg_get_userbyid(m.grantor)) FROM pg_auth_members m),'[]'::jsonb),
 'dynamic_candidates',coalesce((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND p.prokind='f' AND p.prosecdef AND (p.prosrc ~* '\mEXECUTE\M' OR p.proname ~* '(exec.*sql|query.*sql|run.*sql|sql.*exec)')),'[]'::jsonb),
 'incoming_function_references',coalesce((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND p.oid<>to_regprocedure('public.exec_sql(text)') AND n.nspname NOT IN ('pg_catalog','information_schema') AND p.prosrc ILIKE '%exec_sql%'),'[]'::jsonb)
) AS evidence) all_rpc_catalog) r)) AS evidence) combined; IF actual IS DISTINCT FROM '{"rpc":{"dynamic_candidates":[{"acl":"{postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres,authenticated=X/postgres,authenticator=X/postgres,bella_developer=X/postgres,cli_login_postgres=X/postgres,dashboard_user=X/postgres,pg_checkpoint=X/postgres,pg_create_subscription=X/postgres,pg_database_owner=X/postgres,pg_execute_server_program=X/postgres,pg_maintain=X/postgres,pg_monitor=X/postgres,pg_read_all_data=X/postgres,pg_read_all_settings=X/postgres,pg_read_all_stats=X/postgres,pg_read_server_files=X/postgres,pg_signal_backend=X/postgres,pg_stat_scan_tables=X/postgres,pg_use_reserved_connections=X/postgres,pg_write_all_data=X/postgres,pg_write_server_files=X/postgres,pgbouncer=X/postgres,supabase_auth_admin=X/postgres,supabase_etl_admin=X/postgres,supabase_privileged_role=X/postgres,supabase_read_only_user=X/postgres,supabase_realtime_admin=X/postgres,supabase_replication_admin=X/postgres,supabase_storage_admin=X/postgres,verification_executor=X/postgres}","anon_execute":false,"arguments":"sql_query text","definition":"CREATE OR REPLACE FUNCTION public.exec_sql(sql_query text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nBEGIN\r\n  EXECUTE sql_query;\r\nEND;\r\n$function$\n","name":"exec_sql","owner":"postgres","schema":"public"}],"function":{"acl":"{postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres,authenticated=X/postgres,authenticator=X/postgres,bella_developer=X/postgres,cli_login_postgres=X/postgres,dashboard_user=X/postgres,pg_checkpoint=X/postgres,pg_create_subscription=X/postgres,pg_database_owner=X/postgres,pg_execute_server_program=X/postgres,pg_maintain=X/postgres,pg_monitor=X/postgres,pg_read_all_data=X/postgres,pg_read_all_settings=X/postgres,pg_read_all_stats=X/postgres,pg_read_server_files=X/postgres,pg_signal_backend=X/postgres,pg_stat_scan_tables=X/postgres,pg_use_reserved_connecti