a_check","contype":"c","definition":"CHECK (gpa >= 0::numeric AND gpa <= 4.0)","table_name":"students"},{"conname":"students_graduation_dates_check","contype":"c","definition":"CHECK (expected_graduation_date IS NULL OR expected_graduation_date > enrollment_date)","table_name":"students"},{"conname":"students_party_id_fkey","contype":"f","definition":"FOREIGN KEY (party_id) REFERENCES party_parties(id) ON DELETE RESTRICT","table_name":"students"},{"conname":"students_person_fk","contype":"f","definition":"FOREIGN KEY (person_id) REFERENCES persons(id) ON DELETE CASCADE","table_name":"students"},{"conname":"students_pkey","contype":"p","definition":"PRIMARY KEY (student_id)","table_name":"students"},{"conname":"students_student_code_unique","contype":"u","definition":"UNIQUE (tenant_id, student_code)","table_name":"students"},{"conname":"students_tenant_fk","contype":"f","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE","table_name":"students"},{"conname":"students_total_credits_check","contype":"c","definition":"CHECK (total_credits >= 0)","table_name":"students"}],"defaults":[{"acl":"{service_role=rwU/postgres,bella_migration_executor=rwU/postgres}","namespace":"public","object_type":"S","owner":"postgres"},{"acl":"{service_role=X/postgres}","namespace":"public","object_type":"f","owner":"postgres"},{"acl":"{service_role=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,verification_executor=r/postgres}","namespace":"public","object_type":"r","owner":"postgres"}],"functions":[{"acl":"{=X/supabase_auth_admin,postgres=X/supabase_auth_admin,supabase_auth_admin=X/supabase_auth_admin,dashboard_user=X/supabase_auth_admin}","arguments":"","definition":"CREATE OR REPLACE FUNCTION auth.jwt()\n RETURNS jsonb\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n    coalesce(\n        nullif(current_setting(''request.jwt.claim'', true), ''''),\n        nullif(current_setting(''request.jwt.claims'', true), '''')\n    )::jsonb\n$function$\n","name":"jwt","owner":"supabase_auth_admin","proconfig":null,"schema":"auth","security_definer":false},{"acl":"{=X/supabase_auth_admin,supabase_auth_admin=X/supabase_auth_admin,dashboard_user=X/supabase_auth_admin}","arguments":"","definition":"CREATE OR REPLACE FUNCTION auth.uid()\n RETURNS uuid\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n  coalesce(\n    nullif(current_setting(''request.jwt.claim.sub'', true), ''''),\n    (nullif(current_setting(''request.jwt.claims'', true), '''')::jsonb ->> ''sub'')\n  )::uuid\n$function$\n","name":"uid","owner":"supabase_auth_admin","proconfig":null,"schema":"auth","security_definer":false},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"p_tenant_id uuid, p_student_party_id uuid, p_course_id uuid, p_enrollment_id uuid, p_enrolled_at timestamp with time zone, p_request_id text","definition":"CREATE OR REPLACE FUNCTION public.edu_enroll_student_v3(p_tenant_id uuid, p_student_party_id uuid, p_course_id uuid, p_enrollment_id uuid, p_enrolled_at timestamp with time zone, p_request_id text)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  v_max_students INTEGER;\n  v_current_enrollment INTEGER;\n  v_course_status TEXT;\n  v_existing_id UUID;\n  v_rows_affected INTEGER;\nBEGIN\n  -- 1. Pre-lock check for duplicate requests\n  SELECT id INTO v_existing_id\n  FROM public.edu_enrollments\n  WHERE tenant_id = p_tenant_id AND request_id = p_request_id;\n\n  IF FOUND THEN\n    RETURN json_build_object(''success'', true, ''enrollment_id'', v_existing_id, ''is_duplicate'', true);\n  END IF;\n\n  -- 2. Lock course row to ensure concurrent transactional safety\n  SELECT status, max_students, current_enrollment\n  INTO v_course_status, v_max_students, v_current_enrollment\n  FROM public.edu_courses\n  WHERE id = p_course_id AND tenant_id = p_tenant_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION ''Course not found'' USING ERRCODE = ''P0002'';\n  END IF;\n\n  -- 2.5 Post-lock recheck of request_id (prevents race condition where wait for lock results in capacity error instead of duplicate response)\n  SELECT id INTO v_existing_id\n  FROM public.edu_enrollments\n  WHERE tenant_id = p_tenant_id AND request_id = p_request_id;\n\n  IF FOUND THEN\n    RETURN json_build_object(''success'', true, ''enrollment_id'', v_existing_id, ''is_duplicate'', true);\n  END IF;\n\n  -- 3. Check capacity safely\n  IF v_course_status = ''full'' OR (v_max_students IS NOT NULL AND v_current_enrollment >= v_max_students) THEN\n    RAISE EXCEPTION ''Course capacity exceeded'' USING ERRCODE = ''P0003'';\n  END IF;\n\n  -- 4. Create enrollment record with ON CONFLICT DO NOTHING to handle concurrent race conditions\n  INSERT INTO public.edu_enrollments (\n    id, tenant_id, student_party_id, course_id, status, enrolled_at, created_at, updated_at, request_id\n  ) VALUES (\n    p_enrollment_id, p_tenant_id, p_student_party_id, p_course_id, ''active'', p_enrolled_at, now(), now(), p_request_id\n  ) ON CONFLICT (tenant_id, request_id) DO NOTHING;\n\n  GET DIAGNOSTICS v_rows_affected = ROW_COUNT;\n\n  -- 5. If conflict occurred, return the duplicate enrollment details\n  IF v_rows_affected = 0 THEN\n    SELECT id INTO v_existing_id\n    FROM public.edu_enrollments\n    WHERE tenant_id = p_tenant_id AND request_id = p_request_id;\n    \n    RETURN json_build_object(''success'', true, ''enrollment_id'', v_existing_id, ''is_duplicate'', true);\n  END IF;\n\n  -- 6. Increment course current enrollment count\n  v_current_enrollment := v_current_enrollment + 1;\n  UPDATE public.edu_courses\n  SET current_enrollment = v_current_enrollment,\n      updated_at = now()\n  WHERE id = p_course_id AND tenant_id = p_tenant_id;\n\n  RETURN json_build_object(''success'', true, ''enrollment_id'', p_enrollment_id, ''is_duplicate'', false);\nEND;\n$function$\n","name":"edu_enroll_student_v3","owner":"postgres","proconfig":null,"schema":"public","security_definer":false},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.fn_check_invoice_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n    IF OLD.invoice_status IN (''ISSUED'', ''VOID'') THEN\r\n        -- Allow updating settlement_status, paid_amount, outstanding_amount, sha256_checksum, and updated_at ONLY\r\n        IF (OLD.invoice_number IS DISTINCT FROM NEW.invoice_number) OR\r\n           (OLD.gross_amount IS DISTINCT FROM NEW.gross_amount) OR\r\n           (OLD.discount_amount IS DISTINCT FROM NEW.discount_amount) OR\r\n           (OLD.net_amount IS DISTINCT FROM NEW.net_amount) OR\r\n           (OLD.student_id IS DISTINCT FROM NEW.student_id) OR\r\n           (OLD.student_party_id IS DISTINCT FROM NEW.student_party_id) OR\r\n           (OLD.billing_period_id IS DISTINCT FROM NEW.billing_period_id) THEN\r\n            RAISE EXCEPTION ''INVOICE_PUBLISHED_IMMUTABLE_ERROR: Issued invoices are immutable and cannot have header amounts or core fields modified.'';\r\n        END IF;\r\n    END IF;\r\n    RETURN NEW;\r\nEND;\r\n$function$\n","name":"fn_check_invoice_immutable","owner":"postgres","proconfig":null,"schema":"public","security_definer":false},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.fn_check_invoice_line_items_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    parent_status VARCHAR(30);\nBEGIN\n    SELECT invoice_status INTO parent_status FROM public.edu_fin_invoices WHERE id = OLD.invoice_id;\n    IF parent_status IN (''ISSUED'', ''VOID'') THEN\n        RAISE EXCEPTION ''INVOICE_LINE_ITEMS_IMMUTABLE_ERROR: Cannot mutate line items of an issued invoice.'';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n","name":"fn_check_invoice_line_items_immutable","owner":"postgres","proconfig":null,"schema":"public","security_definer":false},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.fn_check_sent_snapshot_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RAISE EXCEPTION ''SENT_SNAPSHOT_IMMUTABLE_ERROR: Dispatched communication snapshots are immutable and cannot be updated or deleted.'';\nEND;\n$function$\n","name":"fn_check_sent_snapshot_immutable","owner":"postgres","proconfig":null,"schema":"public","security_definer":false},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.get_auth_tenant_id()\n RETURNS uuid\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE\n  v_tenant_id uuid;\nBEGIN\n  SELECT u.tenant_id INTO v_tenant_id\n  FROM public.users AS u\n  JOIN public.tenants AS t ON t.id = u.tenant_id\n  WHERE u.id = auth.uid() AND u.status = ''active'' AND t.status = ''active'';\n\n  -- NULL would enable legacy policies using NULL as an unrestricted HQ sentinel.\n  IF v_tenant_id IS NULL THEN\n    RAISE EXCEPTION ''Active canonical identity and tenant required'' USING ERRCODE = ''42501'';\n  END IF;\n  RETURN v_tenant_id;\nEND;\n$function$\n","name":"get_auth_tenant_id","owner":"postgres","proconfig":["search_path=pg_catalog, public"],"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.get_my_tenant_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE\nAS $function$\r\n  SELECT tenant_id FROM public.users WHERE id = auth.uid();\r\n$function$\n","name":"get_my_tenant_id","owner":"postgres","proconfig":null,"schema":"public","security_definer":false},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.is_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.users AS u JOIN public.tenants AS t ON t.id = u.tenant_id\n    WHERE u.id = auth.uid() AND u.status = ''active'' AND t.status = ''active'' AND u.role = ''admin''\n  );\n$function$\n","name":"is_admin","owner":"postgres","proconfig":["search_path=pg_catalog, public"],"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.is_hq_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n  SELECT public.is_hq_super_admin();\n$function$\n","name":"is_hq_admin","owner":"postgres","proconfig":["search_path=pg_catalog, public"],"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.is_hq_super_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.users AS u JOIN public.tenants AS t ON t.id = u.tenant_id\n    WHERE u.id = auth.uid() AND u.status = ''active'' AND t.status = ''active''\n      AND u.role = ''admin'' AND t.product_key = ''bella_hq''\n  );\n$function$\n","name":"is_hq_super_admin","owner":"postgres","proconfig":["search_path=pg_catalog, public"],"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.update_students_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  NEW.updated_at = NOW();\n  RETURN NEW;\nEND;\n$function$\n","name":"update_students_updated_at","owner":"postgres","proconfig":null,"schema":"public","security_definer":false}],"grants":[{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"DELETE","table_name":"edu_comm_acknowledgements"},{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"INSERT","table_name":"edu_comm_acknowledgements"},{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"MAINTAIN","table_name":"edu_comm_acknowledgements"},{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"REFERENCES","table_name":"edu_comm_acknowledgements"},{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"SELECT","table_name":"edu_comm_acknowledgements"},{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"TRIGGER","table_name":"edu_comm_acknowledgements"},{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"TRUNCATE","table_name":"edu_comm_acknowledgements"},{"grantee":"authenticated","grantor":"postgres","is_grantable":false,"privilege_type":"UPDATE","table_name":"edu_comm_acknowledgements"},{"grantee":"bella_developer","grantor":"postgres","is_grantable":false,"privilege_type":"SELECT","table_name":"edu_comm_acknowledgements"},{"grantee":"bella_migration_executor","grantor":"postgres","is_grantable":false,"privilege_type":"DELETE","table_name":"edu_comm_acknowledgements"},{"grantee":"bella_migration_executor","grantor":"postgres","is_grantable":false,"privilege_type":"INSERT","table_name":"edu_comm_acknowledgements"},{"grantee":"bella_migration_executor","grantor":"postgres","is_grantable":false,"privilege_type":"MAINTAIN","table_name":"edu_comm_acknowledgements"},{"grantee":"bella_migration_executor","grantor":"postgres","is_grantable":false,"privilege_type":"REFERENCES","table_nam